import math

def count_triangles(adj):
    n = len(adj)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j]:
                for k in range(j + 1, n):
                    if adj[i][k] and adj[j][k]:
                        count += 1
    return count

def count_tetrahedra(adj):
    n = len(adj)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j]:
                for k in range(j + 1, n):
                    if adj[i][k] and adj[j][k]:
                        for l in range(k + 1, n):
                            if adj[i][l] and adj[j][l] and adj[k][l]:
                                count += 1
    return count

def check_graph(n, edges):
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = adj[v][u] = True
    f = count_triangles(adj)
    g = count_tetrahedra(adj)
    if f > 0:
        return (g**3) / (f**4)
    return 0

